export const NATIVE_BUBBLE_THEME_CSS = "@layer default {\n  /* 轻语气泡 · Soft Whisper\n * 在原生公共部件上覆盖外观，不改变事件内容和交互。\n * 配色集中在区域，尺寸跟随基准字号；公共参数仍可单独覆盖。\n * 常用覆盖：--event-padding（内边距）、--event-gap（间隔）、\n * --avatar-size（头像）、--gift-icon-size（礼物图）、--price-font-size（价格）。\n */\n\n  /* 一、浅色与深色配色。用户名和身份标识沿用软件原有颜色。 */\n  .event-area {\n    --text-body: #303238;\n    --text-secondary: #4f5a57;\n    --bubble-surface: #ffffffed;\n    --bubble-border: #ffffffb0;\n    --bubble-honor-ink: #805b35;\n    --bubble-honor-border: #c7a579;\n    --event-default-line-height: 1.25;\n    background: transparent;\n    box-shadow: none;\n    --text-name: rgb(25, 39, 59);\n  }\n\n  .dark .event-area {\n    --text-name: rgb(222, 225, 229);\n    --text-body: #f0eff3;\n    --text-secondary: #c5ccd4;\n    --bubble-surface: #3c3e49f2;\n    --bubble-border: #ffffff20;\n    --bubble-honor-ink: #dfbc8d;\n    --bubble-honor-border: #a78b67;\n  }\n\n  /* 四边留白统一由列表提供，保留头像框的外伸。 */\n  .event-list {\n    padding: calc(var(--event-font-size) * 0.25);\n  }\n  .event .repeat-count {\n    padding: 0 calc(var(--event-font-size) * 0.375);\n  }\n\n  /* 二、公共尺寸与表面。16px 基准：辅助文字14px，细节12px，行高20px。 */\n\n  .event.type-gift {\n    --bubble-fill: #f5f0e7;\n    --bubble-price: rgb(128, 91, 53);\n  }\n  .event.guard-purchase-level-3 {\n    --bubble-fill: #e9f1ff;\n    --bubble-price: rgb(53, 103, 160);\n  }\n  .event.guard-purchase-level-2 {\n    --bubble-fill: #f3eafb;\n    --bubble-price: rgb(120, 75, 155);\n  }\n  .event.guard-purchase-level-1 {\n    --bubble-fill: #fcece1;\n    --bubble-price: rgb(148, 81, 40);\n  }\n  .event.type-lottery {\n    --bubble-fill: #f1ebfc;\n    --bubble-price: rgb(116, 83, 155);\n  }\n  .event.type-redpocket {\n    --bubble-fill: #fceae6;\n    --bubble-price: rgb(161, 69, 64);\n  }\n\n  /* 公共气泡：宽度贴合内容，尺寸沿用基准字号和原有参数。 */\n  .event {\n    --event-text-color: var(--text-body);\n    --event-secondary-color: var(--message-color, var(--text-secondary));\n    --event-muted-color: var(--message-color, var(--text-secondary));\n    --bubble-fill: var(--bubble-surface);\n    font-size: var(--event-font-size);\n    line-height: var(--event-line-height, 1.25);\n    color: var(--message-color, var(--text-body));\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, calc(var(--event-font-size) * 0.75));\n    border: calc(var(--event-font-size) / 16) solid var(--bubble-border);\n    border-radius: calc(var(--event-font-size) * 1.5);\n    background: var(--event-background, var(--event-background-color, var(--bubble-fill)));\n    box-shadow: 0 calc(var(--event-font-size) * 0.125) calc(var(--event-font-size) * 0.375)\n      #39293608;\n  }\n  .dark .event {\n    box-shadow: none;\n  }\n  .event:not(.event-sticky) {\n    width: fit-content;\n  }\n  .event .price {\n    font-size: var(--price-font-size, inherit);\n    line-height: inherit;\n    font-family: inherit;\n    font-weight: 700;\n    color: var(--price-color, var(--bubble-price, var(--text-body)));\n  }\n  .event :is(.username, .gift-name, .guard-name) {\n    font-weight: 700;\n  }\n  .event .blind-profit {\n    font-family: inherit;\n    font-weight: 700;\n  }\n  .dark .event.type-gift {\n    --bubble-price: #e0c39b;\n    --bubble-fill: #444139;\n  }\n  .dark .event.guard-purchase-level-3 {\n    --bubble-price: #abcdf8;\n    --bubble-fill: #33435c;\n  }\n  .dark .event.guard-purchase-level-2 {\n    --bubble-price: #d9bbf1;\n    --bubble-fill: #493852;\n  }\n  .dark .event.guard-purchase-level-1 {\n    --bubble-price: #efc29c;\n    --bubble-fill: #503b33;\n  }\n  .dark .event.type-lottery {\n    --bubble-price: #d3bcf0;\n    --bubble-fill: #40384f;\n  }\n  .dark .event.type-redpocket {\n    --bubble-price: #f1b8af;\n    --bubble-fill: #503938;\n  }\n\n  /* 头像固定在文字列左侧，后续行不退回头像下面。 */\n  .event-list .event.type-chat:has(> .avatar-wrap) {\n    padding-left: calc(\n      var(--event-padding, var(--event-font-size) * 0.75) +\n        var(--avatar-size, var(--event-font-size) * 1.5) +\n        var(--event-gap, var(--event-font-size) * 0.5)\n    );\n    min-height: calc(\n      var(--avatar-size, var(--event-font-size) * 1.5) +\n        var(--event-padding, var(--event-font-size) * 0.5) * 2\n    );\n  }\n  .event-list .event.type-chat > .avatar-wrap {\n    position: absolute;\n    top: var(--event-padding, calc(var(--event-font-size) * 0.5));\n    left: var(--event-padding, calc(var(--event-font-size) * 0.75));\n    margin: 0;\n  }\n  .event-list .event.type-chat > .user {\n    max-width: 100%;\n    vertical-align: top;\n  }\n  .event-list .event.type-chat > .content {\n    display: inline;\n  }\n  .event-list .event.type-chat:has(:is(.big-emote, .banner-emote))\n    :is(.user, .message, .repeat-count) {\n    vertical-align: top;\n  }\n\n  /* 弹幕与互动保持自然行流，表情和连击不另起整行。 */\n  .event-list .event:is(.type-chat, .type-interaction) > :is(.avatar-wrap, .user) {\n    vertical-align: middle;\n  }\n  .event-list .event.type-interaction {\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.25))\n      var(--event-padding, calc(var(--event-font-size) * 0.75));\n    background: var(--event-background, transparent);\n    box-shadow: none;\n    font-size: calc(var(--event-font-size) * 0.875);\n    border: 0;\n  }\n  .event-list .event.type-interaction > .avatar-wrap {\n    margin-right: var(--event-gap, calc(var(--event-font-size) * 0.5));\n  }\n  .event-list .event.type-interaction:has(> .avatar-wrap) > .user {\n    max-width: calc(100% - var(--avatar-size, var(--event-font-size) * 1.5)\n      - var(--event-gap, var(--event-font-size) * 0.5)\n      - var(--event-gap, var(--event-font-size) * 0.25));\n  }\n  .event .time {\n    font-size: calc(var(--event-font-size) * 0.75);\n    color: var(--message-color, var(--text-secondary));\n  }\n  .event-list .event.type-chat:has(> .time) {\n    max-width: calc(\n      100% - var(--bubble-time-width, var(--event-font-size) * 2.5) -\n        var(--event-font-size) * 0.125\n    );\n  }\n  .event-list .event.type-interaction > .time {\n    position: static;\n    display: inline;\n    margin-left: calc(var(--event-font-size) * 0.25);\n  }\n  .event .time-seconds {\n    display: none;\n  }\n\n  /* 礼物与大航海：宽幅接续用户，窄幅各行自然排列。 */\n  .event-list .event:is(.type-gift, .type-guard) {\n    display: block;\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .avatar-wrap {\n    float: left;\n    margin: 0 var(--event-gap, calc(var(--event-font-size) * 0.5)) 0 0;\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .user {\n    margin-right: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    max-width: calc(\n      100% -\n        var(--avatar-size, calc(var(--event-font-size) * var(--event-config-avatar-scale, 1.5))) -\n        var(--event-gap, calc(var(--event-font-size) * 0.5)) -\n        var(--event-gap, calc(var(--event-font-size) * 0.25))\n    );\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .content {\n    display: inline;\n  }\n  .event-list .event .gift-icon {\n    width: var(--gift-icon-size, calc(var(--event-font-size) * 1.5));\n    height: var(--gift-icon-size, calc(var(--event-font-size) * 1.5));\n  }\n  .event .guard-purchase-icon {\n    width: var(--gift-icon-size, var(--event-font-size));\n    height: var(--gift-icon-size, var(--event-font-size));\n  }\n  .event-list .event .blind-gift {\n    display: inline-flex;\n    flex-basis: auto;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    margin: 0 0 0 var(--event-gap, calc(var(--event-font-size) * 0.25));\n    vertical-align: middle;\n  }\n  .event .blind-gift .price {\n    font-size: var(--price-font-size, inherit);\n  }\n  .event .guard-companion-days {\n    flex-basis: 100%;\n    font-size: inherit;\n  }\n  .event-list .event:is(.type-gift, .type-guard) .content > :is(.action, .gift, .guard, .price) {\n    display: inline-flex;\n    align-items: center;\n    vertical-align: middle;\n    min-height: var(--avatar-size, calc(var(--event-font-size) * 1.5));\n  }\n  .event-list .event:is(.type-gift, .type-guard) .content > :is(.gift-icon, .guard-purchase-icon) {\n    display: inline-flex;\n    vertical-align: middle;\n  }\n  .event-list .event:is(.type-gift, .type-guard) .content > :is(.action, .gift-icon, .gift, .guard-purchase-icon, .guard) {\n    margin-right: var(--event-gap, calc(var(--event-font-size) * 0.25));\n  }\n  /* 陪伴说明从头像后的文字列另起一行。 */\n  .event-list .event:is(.type-gift, .type-guard) .content > .guard-companion-days {\n    margin-top: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    margin-left: calc(\n      var(--avatar-size, calc(var(--event-font-size) * var(--event-config-avatar-scale, 1.5))) +\n        var(--event-gap, calc(var(--event-font-size) * 0.5))\n    );\n  }\n  .event-list .event:is(.type-gift, .type-guard):not(:has(> .avatar-wrap)) > .user {\n    max-width: 100%;\n  }\n  .event-list .event:is(.type-gift, .type-guard):not(:has(> .avatar-wrap)) .content > .guard-companion-days {\n    margin-left: 0;\n  }\n\n  /* SC 金额与用户共用信息行，不保留事件图标空位。 */\n  .event.type-superchat {\n    --bubble-fill: #fbe7ef;\n    --bubble-price: #ab3f61;\n  }\n  .event-list .event.type-superchat {\n    display: block;\n    border-radius: calc(var(--event-font-size) * 1.125);\n  }\n  .dark .event.type-superchat {\n    --bubble-price: #f4b4cc;\n    --bubble-fill: #513a46;\n  }\n  .event-list .event.type-superchat > .info {\n    display: flex;\n    flex-wrap: nowrap;\n    align-items: start;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.5));\n    padding: 0;\n  }\n  .event-list .event.type-superchat .info > .avatar-wrap {\n    align-self: start;\n    margin: 0;\n  }\n  .event-list .event.type-superchat .info > .user {\n    flex: 1 1 auto;\n    min-width: 0;\n    margin: 0;\n    max-width: none;\n  }\n  .event-list .event.type-superchat .info > .price {\n    line-height: var(--avatar-size, calc(var(--event-font-size) * 1.5));\n    margin: 0;\n  }\n  .event-list .event.type-superchat .info > .event-icon {\n    display: none;\n  }\n  .event-list .event.type-superchat > .content {\n    display: block;\n    padding: 0;\n    margin-top: calc(var(--event-font-size) * 0.25);\n  }\n  .event-list .event.type-superchat:has(.info > .avatar-wrap) > .content {\n    margin-left: calc(\n      var(--avatar-size, var(--event-font-size) * 1.5) +\n        var(--event-gap, var(--event-font-size) * 0.5)\n    );\n  }\n\n  .event-list .event.type-superchat > .content > .message {\n    display: inline;\n  }\n  .event .bili-translation {\n    margin-top: calc(var(--event-font-size) * 0.5);\n    padding-top: calc(var(--event-font-size) * 0.5);\n    border-top: calc(var(--event-font-size) / 16) solid var(--bubble-border);\n    color: var(--message-color, var(--text-secondary));\n    font-size: calc(var(--event-font-size) * 0.875);\n  }\n\n  /* 活动标题、状态及正文用已有网格排列。 */\n  .event-list .event:is(.lottery-start, .redpocket-start) {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) auto;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.25))\n      var(--event-gap, calc(var(--event-font-size) * 0.5));\n    border-radius: calc(var(--event-font-size) * 1.125);\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start):has(> .avatar-wrap) {\n    grid-template-columns: auto minmax(0, 1fr) auto;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .avatar-wrap {\n    grid-column: 1;\n    grid-row: 1;\n    align-self: center;\n    margin: 0;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > :is(.user, .activity-title) {\n    grid-column: -3;\n    grid-row: 1;\n    max-width: 100%;\n    margin: 0;\n  }\n  .event-list .event.lottery-start > .activity-title {\n    padding-left: calc(var(--event-font-size) * 1.25);\n  }\n  .event-list .event.lottery-start > .event-icon {\n    grid-column: -3;\n    grid-row: 1;\n    width: var(--event-font-size);\n    height: var(--event-font-size);\n    align-self: center;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .content {\n    grid-column: -3 / -1;\n    grid-row: 2;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .activity-status {\n    grid-column: -2;\n    grid-row: 1;\n    position: static;\n    justify-self: end;\n    margin: 0;\n  }\n  .event\n    :is(\n      .lottery-command,\n      .lottery-required-gift,\n      .lottery-requirement,\n      .redpocket-awards,\n      .redpocket-command\n    ) {\n    display: block;\n    margin: calc(var(--event-font-size) * 0.25) 0 0;\n    line-height: inherit;\n  }\n  .event :is(.lottery-command, .redpocket-command) > .prefix {\n    margin-right: calc(var(--event-font-size) * 0.25);\n  }\n  .event :is(.lottery-name, .redpocket-name, .activity-prize) {\n    color: inherit;\n    font-weight: 700;\n  }\n  .event .redpocket {\n    display: block;\n  }\n\n  /* 开奖名单保留首行按钮及原生 details 展开。 */\n  .event-list .event:is(.lottery-result, .redpocket-result) {\n    display: grid;\n    grid-template-columns: auto minmax(0, 1fr);\n    gap: 0 calc(var(--event-font-size) * 0.25);\n    border-radius: calc(var(--event-font-size) * 1.125);\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .event-icon {\n    grid-column: 1;\n    grid-row: 1;\n    width: var(--event-font-size);\n    height: var(--event-font-size);\n    margin: 0;\n    align-self: center;\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .result-title {\n    grid-column: 2;\n    grid-row: 1;\n    display: block;\n    padding: 0;\n    color: inherit;\n    font-size: calc(var(--event-font-size) * 0.875);\n    font-weight: 700;\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .content {\n    grid-column: 1 / -1;\n    grid-row: 2;\n    display: block;\n    margin-top: calc(var(--event-font-size) * 0.25);\n  }\n  .event .result-description {\n    font-size: calc(var(--event-font-size) * 0.875);\n    font-weight: 700;\n    color: var(--text-body);\n  }\n  .event .winner-list-toggle {\n    top: calc(var(--event-font-size) * 0.5);\n    right: calc(var(--event-font-size) * 0.75);\n    font-size: calc(var(--event-font-size) * 0.75);\n    line-height: 1.5;\n  }\n  .event .winner-list-items {\n    margin-top: calc(var(--event-font-size) * 0.5);\n    padding-top: calc(var(--event-font-size) * 0.5);\n    border-color: var(--bubble-border);\n  }\n  .event .winner-list-item {\n    font-size: calc(var(--event-font-size) * 0.875);\n  }\n\n  .event-list .event:is(.lottery-result, .redpocket-result):has(.winner-list) > .result-title {\n    padding-right: calc(var(--event-font-size) * 2.5);\n  }\n\n  /* 成就保留官方图片、双轮廓和两行文字。 */\n  .event-list .event.type-guard-honor {\n    --bubble-fill: #fbefdf;\n    display: flex;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.75));\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, var(--event-font-size));\n    border: calc(var(--event-font-size) / 16) solid var(--bubble-honor-border);\n    border-radius: calc(var(--event-font-size) * 1.125);\n    color: var(--bubble-honor-ink);\n    box-shadow: none;\n  }\n  .dark .event.type-guard-honor {\n    --bubble-fill: #3e3733;\n  }\n  .event-list .event.type-guard-honor > .avatar-wrap {\n    flex: none;\n    width: var(--avatar-size, calc(var(--event-font-size) * 1.5));\n    height: var(--avatar-height, var(--avatar-size, calc(var(--event-font-size) * 1.5)));\n    margin: 0;\n  }\n  .event-list .event.type-guard-honor > .content {\n    flex: 1;\n    min-width: 0;\n    padding: 0 0 0 calc(var(--event-font-size) * 0.75);\n    border-left: calc(var(--event-font-size) / 16) solid var(--bubble-honor-border);\n  }\n  .event-list .event.type-guard-honor:not(:has(> .avatar-wrap)) > .content {\n    padding-left: 0;\n    border-left: 0;\n  }\n  .event-list .event.type-guard-honor .honor-icon {\n    position: static;\n    order: 1;\n    flex: none;\n    transform: none;\n    width: calc(var(--event-font-size) * 3.5);\n    height: calc(var(--event-font-size) * 3.5);\n    opacity: 1;\n  }\n  .event :is(.honor-heading, .honor-summary) {\n    font-size: calc(var(--event-font-size) * 0.875);\n    line-height: calc(var(--event-font-size) * 1.25);\n  }\n  .event .honor-summary {\n    margin-top: calc(var(--event-font-size) * 0.25);\n  }\n  .event :is(.honor-highlight, .honor-milestone) {\n    color: var(--bubble-honor-ink);\n  }\n  .event .honor-milestone {\n    position: static;\n    font-size: inherit;\n    margin-left: calc(var(--event-font-size) * 0.25);\n    transform: none;\n  }\n  .event-list .event.type-guard-honor::after {\n    inset: calc(var(--event-font-size) * 0.25);\n    border-radius: calc(var(--event-font-size) * 0.875);\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16)\n      color-mix(in srgb, var(--bubble-honor-border) 45%, transparent);\n  }\n\n  /* 系统消息按内容收窄，时间优先与标题同行。 */\n  .event-list .event:is(.type-system, .type-live-status, .type-unknown) {\n    display: block;\n    padding-top: calc(var(--event-font-size) * 0.25);\n    padding-bottom: calc(var(--event-font-size) * 0.25);\n    padding-right: var(--event-padding, calc(var(--event-font-size) * 1.25));\n  }\n  .event-list .event .system-message {\n    color: var(--message-color, var(--text-secondary));\n    font-size: calc(var(--event-font-size) * 0.875);\n    font-weight: 500;\n    line-height: calc(var(--event-font-size) * var(--event-line-height, 1.25));\n  }\n  .event-list .event .system-message-title {\n    font-weight: inherit;\n  }\n  .event-list .event :is(.system-message-detail, .system-message-expiry) {\n    font-size: inherit;\n    font-weight: inherit;\n    margin-top: calc(var(--event-font-size) * 0.25);\n  }\n  .event .lifecycle-time {\n    font-size: inherit;\n    margin-left: calc(var(--event-font-size) * 0.5);\n    color: inherit;\n    font-weight: inherit;\n  }\n  .event-list .event.live-warning {\n    --bubble-fill: #fff0cc;\n    color: var(--message-color, #754000);\n    border-color: #d99a30;\n  }\n  .event-list .event:is(.live-cutoff, .live-locked) {\n    --bubble-fill: #ffe1df;\n    color: var(--message-color, #a52626);\n    border-color: #d76767;\n  }\n  .dark .event-list .event.live-warning {\n    --bubble-fill: #514025;\n    color: var(--message-color, #ffda8a);\n    border-color: #b68c43;\n  }\n  .dark .event-list .event:is(.live-cutoff, .live-locked) {\n    --bubble-fill: #542c34;\n    color: var(--message-color, #ffc0bc);\n    border-color: #bb6570;\n  }\n  .event-list .event:is(.live-warning, .live-cutoff, .live-locked) {\n    padding-top: calc(var(--event-font-size) * 0.5);\n    padding-bottom: calc(var(--event-font-size) * 0.5);\n  }\n  .event-list .event:is(.live-warning, .live-cutoff, .live-locked) .system-message {\n    color: inherit;\n    font-weight: 700;\n  }\n\n  /* 置顶保持已有的单行胶囊布局。 */\n  .event.event-sticky {\n    display: flex;\n    flex-wrap: nowrap;\n    align-items: center;\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.25))\n      var(--event-padding, calc(var(--event-font-size) * 0.375));\n    border: 0;\n    border-radius: calc(var(--event-font-size) * 999);\n    box-shadow: none;\n    color: var(--message-color, var(--bubble-price, var(--text-body)));\n  }\n  .event.event-sticky > .content {\n    flex-wrap: nowrap;\n  }\n  .event.event-sticky .blind-gift {\n    flex: none;\n  }\n  .event.event-sticky .avatar-wrap {\n    align-self: center;\n    width: var(--avatar-size, var(--event-font-size));\n    height: var(--avatar-height, var(--avatar-size, var(--event-font-size)));\n  }\n  .event.event-sticky :is(.price, .lottery, .blind-profit) {\n    font-size: var(--price-font-size, calc(var(--event-font-size) * 0.875));\n    line-height: calc(var(--event-font-size) * var(--event-line-height, 1.25));\n    font-weight: 700;\n  }\n  .event.event-sticky :is(.price, .lottery) {\n    color: var(--price-color, var(--message-color, var(--bubble-price, var(--text-body))));\n  }\n\n  @container native-events (max-width: 20em) {\n    .event-list .event:is(.type-gift, .type-guard) > .content {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n      width: 100%;\n      clear: both;\n    }\n    .event-list .event:is(.type-gift, .type-guard) .content > :is(.action, .gift-icon, .gift, .guard-purchase-icon, .guard) {\n      margin-right: 0;\n    }\n    .event-list .event:is(.type-gift, .type-guard) .content > .guard-companion-days {\n      margin-left: 0;\n      flex-basis: 100%;\n    }\n    .event-list .event .blind-gift {\n      margin-left: 0;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) {\n      column-gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    }\n    .event-list .event:is(.type-gift, .type-guard) > .content {\n      flex-basis: 100%;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) > .activity-status {\n      grid-column: 1 / -1;\n      grid-row: 2;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) > .content {\n      grid-column: 1 / -1;\n      grid-row: 3;\n    }\n    .event-list .event.type-guard-honor {\n      gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n      padding: var(--event-padding, calc(var(--event-font-size) * 0.5));\n    }\n    .event-list .event.type-guard-honor > .content {\n      padding-left: calc(var(--event-font-size) * 0.25);\n    }\n    .event-list .event.type-guard-honor .honor-icon {\n      width: calc(var(--event-font-size) * 2.5);\n      height: calc(var(--event-font-size) * 2.5);\n      margin-left: 0;\n    }\n  }\n\n  .event > .time {\n    position: absolute;\n    left: calc(100% + var(--event-font-size) * 0.125);\n    bottom: 0;\n    display: block;\n    width: max-content;\n    margin: 0;\n    line-height: calc(var(--event-font-size) * 1.25);\n  }\n  .event-list .event:is(\n      .type-gift,\n      .type-guard,\n      .type-superchat,\n      .type-lottery,\n      .type-redpocket,\n      .type-guard-honor\n    )\n    > .time {\n    display: none;\n  }\n}\n";
